package com.oshyky.betterintervalcoach;

import android.app.*;import android.content.*;import android.media.*;import android.os.*;import android.speech.tts.TextToSpeech;import android.speech.tts.UtteranceProgressListener;import java.io.File;import java.util.*;

public class IntervalService extends Service {
 public static final String ACTION_START="START",ACTION_PAUSE="PAUSE",ACTION_RESUME="RESUME",ACTION_SKIP="SKIP",ACTION_STOP="STOP"; private static final String CH="better_timer";private static final int NOTIF=42;
 private final Handler h=new Handler(Looper.getMainLooper()); private final Runnable timerRunnable=this::tick; private TextToSpeech tts;private Vibrator vib;private MediaPlayer voice;private SharedPreferences p;private boolean running=false,paused=false;private String phase="work";private int work=240,rest=180,count=4,current=1;private long phaseEnd=0,pausedRemaining=0;private boolean countdown3,countdown2,countdown1;
 @Override public void onCreate(){super.onCreate();p=getSharedPreferences("timer",MODE_PRIVATE);vib=(Vibrator)getSystemService(VIBRATOR_SERVICE);tts=new TextToSpeech(this,s->{if(s==TextToSpeech.SUCCESS){tts.setLanguage(Locale.UK);tts.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String id){}public void onDone(String id){}public void onError(String id){}});}});restore();createChannel();}
 @Override public int onStartCommand(Intent i,int flags,int id){String a=i==null?null:i.getAction();if(a==null){if(running)startForegroundNow();tick();return START_STICKY;}if(ACTION_START.equals(a))start(i.getIntExtra("work",work),i.getIntExtra("rest",rest),i.getIntExtra("count",count));else if(ACTION_PAUSE.equals(a))pause();else if(ACTION_RESUME.equals(a))resume();else if(ACTION_SKIP.equals(a))skip();else if(ACTION_STOP.equals(a))stopTimer();return START_STICKY;}
 private void start(int w,int r,int c){cancelTimer();work=Math.max(1,w);rest=Math.max(0,r);count=Math.max(1,c);current=1;phase="work";running=true;paused=false;phaseEnd=SystemClock.elapsedRealtime()+work*1000L;pausedRemaining=0;resetCountdown();save();startForegroundNow();buzz(new long[]{0,350});speakOrPlay("Interval start");tick();}
 private void tick(){if(!running)return;if(paused){updateNotification(pausedRemaining);return;}long now=SystemClock.elapsedRealtime();int guard=0;while(running&&!paused&&now>=phaseEnd&&guard++<100){transition();now=SystemClock.elapsedRealtime();}if(!running)return;long left=Math.max(0,phaseEnd-SystemClock.elapsedRealtime());maybeCountdown(left);updateNotification(left);scheduleNext(left);}
 private void scheduleNext(long left){h.removeCallbacks(timerRunnable);long delay=Math.min(250,Math.max(50,left));h.postDelayed(timerRunnable,delay);}
 private void transition(){if("work".equals(phase)){if(current>=count){finish();return;}if(rest<=0){current++;phase="work";phaseEnd=SystemClock.elapsedRealtime()+work*1000L;resetCountdown();changeCue(true);save();return;}phase="rest";phaseEnd=SystemClock.elapsedRealtime()+rest*1000L;resetCountdown();changeCue(false);save();}else{current++;phase="work";phaseEnd=SystemClock.elapsedRealtime()+work*1000L;resetCountdown();changeCue(true);save();}}
 private void maybeCountdown(long left){if(!countdown3&&left<=3000&&left>2000){countdown3=true;speak("3");buzz(new long[]{0,170});}else if(!countdown2&&left<=2000&&left>1000){countdown2=true;speak("2");buzz(new long[]{0,170});}else if(!countdown1&&left<=1000&&left>100){countdown1=true;speak("1");buzz(new long[]{0,170});}}
 private void changeCue(boolean interval){buzz(new long[]{0,350,150,350});if(interval)speakOrPlay("Interval start");else speakOrPlay("Rest");}
 private void finish(){running=false;paused=false;clearSaved();cancelTimer();buzz(new long[]{0,700,250,500,250,900});speak("Workout complete");stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 private void pause(){if(!running||paused)return;pausedRemaining=Math.max(0,phaseEnd-SystemClock.elapsedRealtime());paused=true;save();cancelTimer();buzz(new long[]{0,120});updateNotification(pausedRemaining);}
 private void resume(){if(!running||!paused)return;paused=false;phaseEnd=SystemClock.elapsedRealtime()+pausedRemaining;save();buzz(new long[]{0,120});tick();}
 private void skip(){if(!running)return;phaseEnd=SystemClock.elapsedRealtime();tick();}
 private void stopTimer(){running=false;paused=false;clearSaved();cancelTimer();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 private void speak(String text){if(tts!=null)tts.speak(text,TextToSpeech.QUEUE_FLUSH,null,"better_"+System.nanoTime());}
 private void speakOrPlay(String text){File f=new File(getFilesDir(),"voice.3gp");if(f.exists()){try{if(voice!=null){voice.release();voice=null;}voice=new MediaPlayer();voice.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build());voice.setDataSource(f.getAbsolutePath());voice.setOnPreparedListener(MediaPlayer::start);voice.prepareAsync();return;}catch(Exception ignored){}}speak(text);}
 private void buzz(long[] pattern){if(vib==null)return;try{if(Build.VERSION.SDK_INT>=26)vib.vibrate(VibrationEffect.createWaveform(pattern,-1));else vib.vibrate(pattern,-1);}catch(Exception ignored){}}
 private void createChannel(){if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(CH,"BETTER Timer",NotificationManager.IMPORTANCE_LOW);c.setDescription("Workout timer running in the background");((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c);}}
 private PendingIntent pi(String a){Intent i=new Intent(this,IntervalService.class).setAction(a);return PendingIntent.getService(this,a.hashCode(),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private void startForegroundNow(){startForeground(NOTIF,buildNotification());}
 private Notification buildNotification(){String phaseName="work".equals(phase)?"INTERVAL":"REST";String text=paused?"Paused":phaseName+" • "+fmt(Math.max(0,(phaseEnd-SystemClock.elapsedRealtime())/1000));Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CH):new Notification.Builder(this);b.setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("BETTER Interval Coach").setContentText("#"+current+" / "+count+" • "+text).setOngoing(true).setOnlyAlertOnce(true).setContentIntent(PendingIntent.getActivity(this,1,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));b.addAction(new Notification.Action.Builder(android.R.drawable.ic_media_pause,paused?"Resume":"Pause",pi(paused?ACTION_RESUME:ACTION_PAUSE)).build());b.addAction(new Notification.Action.Builder(android.R.drawable.ic_media_next,"Skip",pi(ACTION_SKIP)).build());b.addAction(new Notification.Action.Builder(android.R.drawable.ic_menu_close_clear_cancel,"Stop",pi(ACTION_STOP)).build());return b.build();}
 private void updateNotification(long left){((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(NOTIF,buildNotification());}
 private String fmt(long s){return String.format(Locale.UK,"%02d:%02d",s/60,s%60);}private void resetCountdown(){countdown3=countdown2=countdown1=false;}private void save(){p.edit().putBoolean("running",running).putBoolean("paused",paused).putString("phase",phase).putInt("work",work).putInt("rest",rest).putInt("count",count).putInt("current",current).putLong("phaseEnd",phaseEnd).putLong("pausedRemaining",pausedRemaining).apply();}private void restore(){running=p.getBoolean("running",false);paused=p.getBoolean("paused",false);phase=p.getString("phase","work");work=p.getInt("work",240);rest=p.getInt("rest",180);count=p.getInt("count",4);current=p.getInt("current",1);phaseEnd=p.getLong("phaseEnd",0);pausedRemaining=p.getLong("pausedRemaining",0);}private void clearSaved(){p.edit().clear().apply();}private void cancelTimer(){h.removeCallbacks(timerRunnable);}
 @Override public void onDestroy(){cancelTimer();if(voice!=null){voice.release();voice=null;}if(tts!=null){tts.stop();tts.shutdown();}super.onDestroy();}@Override public IBinder onBind(Intent i){return null;}
}
